package com.brasa.restaurant.service;import com.brasa.restaurant.dto.Dtos.*;import com.brasa.restaurant.enums.Enums.*;import com.brasa.restaurant.exception.ApiExceptions;import com.brasa.restaurant.mapper.ApiMapper;import com.brasa.restaurant.model.*;import com.brasa.restaurant.repository.Repositories.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.*;@Service public class PublicService{private final RestauranteRepository rr;private final CategoriaRepository cr;private final ProdutoRepository pr;private final PedidoRepository or;private final MesaRepository mr;private final ChamadoRepository chr;public PublicService(RestauranteRepository a,CategoriaRepository b,ProdutoRepository c,PedidoRepository d,MesaRepository e,ChamadoRepository f){rr=a;cr=b;pr=c;or=d;mr=e;chr=f;}private Restaurante restaurant(String slug){return rr.findBySlugAndAtivoTrue(slug).orElseThrow(()->new ApiExceptions.NotFound("Restaurante não encontrado"));}public RestauranteResponse restaurantDto(String slug){return ApiMapper.restaurant(restaurant(slug));}public List<CategoriaDto>categories(String slug){return cr.findByRestauranteIdOrderByOrdemAsc(restaurant(slug).getId()).stream().map(ApiMapper::category).toList();}public List<ProdutoDto>products(String slug){return pr.findByRestauranteIdOrderByNomeAsc(restaurant(slug).getId()).stream().map(ApiMapper::product).toList();}public List<PedidoResponse>tableOrders(String slug,int mesa){return or.findByRestauranteIdAndNumeroMesaAndStatusNotOrderByCriadoEmDesc(restaurant(slug).getId(),mesa,StatusPedido.FECHADO).stream().map(ApiMapper::order).toList();}@Transactional public PedidoResponse createOrder(String slug,CriarPedidoRequest x){Restaurante r=restaurant(slug);Mesa mesa=mr.findByRestauranteIdAndNumero(r.getId(),x.numero_mesa()).orElseThrow(()->new ApiExceptions.NotFound("Mesa não encontrada"));if(mesa.getStatus()==StatusMesa.FECHAMENTO_SOLICITADO)throw new ApiExceptions.Business("A mesa está aguardando fechamento");if(mesa.getStatus()==StatusMesa.FECHADA){mesa.setStatus(StatusMesa.ABERTA);mr.save(mesa);}Pedido p=new Pedido();p.setRestauranteId(r.getId());p.setNumeroMesa(x.numero_mesa());p.setNomeCliente(x.nome_cliente());BigDecimal total=BigDecimal.ZERO;for(var in:x.itens()){Produto prod=pr.findById(in.produto_id()).filter(v->v.getRestauranteId().equals(r.getId())&&v.isDisponivel()).orElseThrow(()->new ApiExceptions.Business("Produto indisponível"));ItemPedido item=new ItemPedido();item.setProdutoId(prod.getId());item.setNomeProduto(prod.getNome());item.setQuantidade(in.quantidade());item.setPrecoUnitario(prod.getPreco());item.setObservacao(in.observacao());p.addItem(item);total=total.add(prod.getPreco().multiply(BigDecimal.valueOf(in.quantidade())));}p.setTotal(total);return ApiMapper.order(or.save(p));}@Transactional public ChamadoResponse call(String slug,ChamadoRequest x){Restaurante r=restaurant(slug);Mesa m=mr.findByRestauranteIdAndNumero(r.getId(),x.numero_mesa()).orElseThrow(()->new ApiExceptions.NotFound("Mesa não encontrada"));Chamado c=new Chamado();c.setRestauranteId(r.getId());c.setNumeroMesa(x.numero_mesa());c.setTipo(x.tipo());if(x.tipo()==TipoChamado.FECHAR_CONTA){m.setStatus(StatusMesa.FECHAMENTO_SOLICITADO);mr.save(m);}return ApiMapper.call(chr.save(c));}public MesaStatusResponse tableStatus(String slug,int mesa){Restaurante r=restaurant(slug);Mesa m=mr.findByRestauranteIdAndNumero(r.getId(),mesa).orElseThrow(()->new ApiExceptions.NotFound("Mesa não encontrada"));return new MesaStatusResponse(mesa,m.getStatus());}}
